// FUNCTION: BFME2 0x00485565 size=590 name=?createCrate@CreateCrateDie@@AAEPAVObject@@PBVCrateTemplate@@@Z evidence=N:ledger tier=A
Object *CreateCrateDie::createCrate(const CrateTemplate *currentCrateData)
{
	PathfindLayerEnum layer = (PathfindLayerEnum)getObject()->rva0028B511();

	Real multipleCratePick = GetGameLogicRandomValueReal(0.0f, 1.0f, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Die\\CreateCrateDie.cpp", 0xA7);
	Real multipleCrateRunningTotal = 0;
	AsciiString crateName = "";

	for (crateCreationEntryList::const_iterator iter = currentCrateData->m_possibleCrates.begin();
			iter != currentCrateData->m_possibleCrates.end();
			iter++)
	{
		multipleCrateRunningTotal += (*iter).crateChance;
		if (multipleCrateRunningTotal > multipleCratePick)
		{
			crateName = (*iter).crateName;
			break;
		}
	}

	const ThingTemplate *crateType = TheThingFactory->findTemplate(crateName);
	if (crateType == NULL)
		return NULL;

	Coord3D centerPoint;
	centerPoint.x = getObject()->getPosition()->x;
	centerPoint.y = getObject()->getPosition()->y;
	centerPoint.z = getObject()->getPosition()->z;
	Bool spotFound = false;
	Coord3D creationPoint;
	FindPositionOptions fpOptions;
	fpOptions.minRadius = 0.0f;
	fpOptions.maxRadius = 5.0f;
	fpOptions.relationshipObject = getObject();
	fpOptions.flags = 8;	// FPF_IGNORE_ALLY_OR_NEUTRAL_UNITS: the dead object and its hulk do not block the crate
	if (layer != LAYER_GROUND)
	{
		creationPoint = centerPoint;
		spotFound = true;
	}
	else if (PartitionManager::findPositionAround(&centerPoint, &fpOptions, &creationPoint))
	{
		spotFound = true;
	}
	else
	{
		fpOptions.minRadius = 0.0f;
		fpOptions.maxRadius = 125.0f;
		fpOptions.relationshipObject = NULL;
		fpOptions.flags = 0;
		if (PartitionManager::findPositionAround(&centerPoint, &fpOptions, &creationPoint))
			spotFound = true;
	}

	if (spotFound)
	{
		CreateMask statusBits;
		memset(&statusBits, 0, sizeof(statusBits));
		Object *newCrate = TheThingFactory->newObject(crateType, NULL, &statusBits, (ObjectID)0);
		newCrate->setPosition(&creationPoint);
		newCrate->setOrientation(GetGameLogicRandomValueReal(0.0f, 2 * 3.1415927f, "C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Die\\CreateCrateDie.cpp", 0xE2));
		newCrate->setLayer(layer);

		Drawable *crateDrawable = newCrate->getDrawable();
		if (crateDrawable)
		{
			crateDrawable->setTerrainDecal((TerrainDecalType)5);
			crateDrawable->rva002728C5(2.5f * newCrate->getGeometryInfo()->getMajorRadius(), 2.5f * newCrate->getGeometryInfo()->getMajorRadius());
			crateDrawable->rva00270644(1.0f, 0.03f);
		}
		return newCrate;
	}
	return NULL;
}


